import{_ as t,o,c as a,a5 as r}from"./chunks/framework.QnCkLuYX.js";const s="/assets/find-and-replace.BhxuJ8lp.png",i="/assets/batch-replace.DuBNO2ZW.png",n="/assets/filters-and-line-tools.BT1c8Ymq.png",b=JSON.parse('{"title":"Productivity Tools","description":"","frontmatter":{},"headers":[],"relativePath":"en_US/04-productivity-tools.md","filePath":"en_US/04-productivity-tools.md"}'),l={name:"en_US/04-productivity-tools.md"};function c(d,e,h,u,p,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="productivity-tools" tabindex="-1">Productivity Tools <a class="header-anchor" href="#productivity-tools" aria-label="Permalink to &quot;Productivity Tools&quot;">​</a></h1><p>Find, filter, batch-edit, and restructure subtitle rows without losing control of the active selection.</p><h2 id="what-you-can-do-on-this-page" tabindex="-1">What you can do on this page <a class="header-anchor" href="#what-you-can-do-on-this-page" aria-label="Permalink to &quot;What you can do on this page&quot;">​</a></h2><ul><li>Search and replace source or translation text.</li><li>Combine filters and quality limits.</li><li>Sort, resize, hide, and reset columns.</li><li>Break, split, merge, add, or delete selected rows.</li></ul><h2 id="find-subtitle-content" tabindex="-1">Find subtitle content <a class="header-anchor" href="#find-subtitle-content" aria-label="Permalink to &quot;Find subtitle content&quot;">​</a></h2><p>Type in the search box to find text across source and translation. Enable <strong>Filter Results</strong> to hide nonmatching rows; disable it to keep all rows visible while matches remain highlighted.</p><p><code>Ctrl+F</code> (<code>Command+F</code> on macOS) focuses the search field. Clearing the query restores the normal result set.</p><h2 id="replace-one-or-all-matches" tabindex="-1">Replace one or all matches <a class="header-anchor" href="#replace-one-or-all-matches" aria-label="Permalink to &quot;Replace one or all matches&quot;">​</a></h2><p>Click <strong>Adv. Search / Replace</strong> or press <code>Ctrl+H</code> (also usable on macOS; or click the button to avoid the system <code>Command+H</code> shortcut).</p><p><img src="'+s+'" alt="Find and Replace tool with search, replacement, and matching options"></p><p>Choose whether to search translations only, match case, use a regular expression, or require a whole-cell match. Use <strong>Replace</strong> for the current match or <strong>Replace All</strong> after checking the match count. Invalid regular expressions are reported without modifying rows.</p><h2 id="use-batch-replacement-rules" tabindex="-1">Use batch replacement rules <a class="header-anchor" href="#use-batch-replacement-rules" aria-label="Permalink to &quot;Use batch replacement rules&quot;">​</a></h2><p>Open <strong>Batch Replace</strong> to maintain an ordered list of find/replacement pairs.</p><p><img src="'+i+'" alt="Batch Replace dialog with three ordered replacement pairs"></p><p>Rules run from top to bottom, so an earlier replacement can affect a later rule. Add, remove, clear, import, or export rules with <code>bad_words.csv</code>, then click <strong>Apply to Translation</strong>. The dialog reports active pairs and rows changed.</p><h2 id="filter-rows-that-need-work" tabindex="-1">Filter rows that need work <a class="header-anchor" href="#filter-rows-that-need-work" aria-label="Permalink to &quot;Filter rows that need work&quot;">​</a></h2><p>Click <strong>Show Filters</strong> and combine field, operator, and value rules with <strong>AND</strong> or <strong>OR</strong>.</p><p><img src="'+n+'" alt="Search, line tools, and a translation filter rule"></p><p>Filters can target episode, source, translation, timing, and other visible data. Long-line and high-CPS counters provide quick specialized filters. Filtered rows remain in the workspace and return when filters are cleared.</p><h2 id="sort-and-adjust-the-grid" tabindex="-1">Sort and adjust the grid <a class="header-anchor" href="#sort-and-adjust-the-grid" aria-label="Permalink to &quot;Sort and adjust the grid&quot;">​</a></h2><p>Click a sortable column header to change order. Drag column boundaries to resize. Use <strong>Show Hidden Columns</strong> in Settings for metadata columns, and <strong>Reset View</strong> to restore the default layout.</p><p>Sorting changes presentation, not row timing or episode ownership. Check the current order before positional copy/paste operations.</p><h2 id="select-multiple-subtitles" tabindex="-1">Select multiple subtitles <a class="header-anchor" href="#select-multiple-subtitles" aria-label="Permalink to &quot;Select multiple subtitles&quot;">​</a></h2><p>Use row checkboxes, the select-all control, or a grid range. Tool labels show the number of selected rows. With filters active, select-all applies to visible rows; verify the count before destructive operations.</p><h2 id="break-long-subtitle-text" tabindex="-1">Break long subtitle text <a class="header-anchor" href="#break-long-subtitle-text" aria-label="Permalink to &quot;Break long subtitle text&quot;">​</a></h2><p>Select rows and click <strong>Break Selected</strong>. The tool inserts line breaks using the project&#39;s line-length limit while preserving each subtitle as one timed row. Rows that do not need changes are reported as unchanged.</p><h2 id="split-subtitle-rows" tabindex="-1">Split subtitle rows <a class="header-anchor" href="#split-subtitle-rows" aria-label="Permalink to &quot;Split subtitle rows&quot;">​</a></h2><p>Select rows and click <strong>Split Selected</strong>. GridSubStudio divides text into multiple rows and distributes timing across the generated rows. Review both semantic boundaries and timing afterward.</p><h2 id="merge-subtitle-rows" tabindex="-1">Merge subtitle rows <a class="header-anchor" href="#merge-subtitle-rows" aria-label="Permalink to &quot;Merge subtitle rows&quot;">​</a></h2><p>Select adjacent rows in the same episode and click <strong>Merge Selected</strong>. Text is joined and timing spans the selected range. Nonadjacent rows, mixed episodes, or incompatible selections are rejected; timing gaps require explicit confirmation.</p><h2 id="add-and-delete-rows" tabindex="-1">Add and delete rows <a class="header-anchor" href="#add-and-delete-rows" aria-label="Permalink to &quot;Add and delete rows&quot;">​</a></h2><p><strong>Add Line</strong> inserts a new subtitle row near the current selection. Fill its episode, timing, source, and translation as needed. <strong>Delete Selected</strong> removes selected rows after confirmation and can be undone before closing the workspace.</p><h2 id="use-the-context-menu-and-shortcuts" tabindex="-1">Use the context menu and shortcuts <a class="header-anchor" href="#use-the-context-menu-and-shortcuts" aria-label="Permalink to &quot;Use the context menu and shortcuts&quot;">​</a></h2><p>Right-click the grid for operations relevant to the current selection. <code>Delete</code>, copy/paste, undo/redo, find, replace, and playback shortcuts reduce toolbar travel. When editing a cell, text-editor shortcuts take priority.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>A tool is disabled:</strong> select the required number of compatible rows.</li><li><strong>Merge is rejected:</strong> make the rows adjacent, within one episode, and clear incompatible filters/order.</li><li><strong>Replace changed too much:</strong> undo immediately and refine case, whole-cell, translation-only, or regex options.</li><li><strong>Selected count is unexpected:</strong> check filters and the select-all state.</li></ul>',36)])])}const w=t(l,[["render",c]]);export{b as __pageData,w as default};
